function makeDialog(id,title){let d=$(id);if(!d){d=document.createElement('dialog');d.id=id;document.body.append(d)}d.classList.add('action-dialog');d.replaceChildren();const close=document.createElement('button');close.className='dialog-close';close.textContent='Close ×';close.onclick=()=>d.close();const h=document.createElement('h2');h.textContent=title;h.tabIndex=-1;h.autofocus=true;d.append(close,h);return d;}
function openActions(a){const d=makeDialog('interactionDialog',a.profile.name);if(a.userId&&a.userId!==session.userId){const chat=document.createElement('button');chat.textContent='Message';chat.onclick=()=>{d.close();phone.open(a.userId)};d.append(chat)}if(!canControl(a,session,embedded)){const p=document.createElement('p');p.textContent=online(a)?'This employee controls their own avatar. Invite them from Leisure.':'Offline employee · autonomous campus activity';d.append(p);d.showModal();return}
 const actions={Social:{wave:'Wave',greet:'Greet',handshake:'Shake hands',talk:'Chat',laugh:'Laugh',clap:'Clap',cheer:'Cheer',selfie:'Take selfie',dance:'Dance'},Movement:{walk:'Walk',followActor:'Follow a companion',idle:'Stand',sit:'Sit'},...(a.floor==='1'?{Office:{work:'Work at computer',type:'Type',mouse:'Use mouse',read:'Read documents',phone:'Answer phone',meeting:'Attend meeting'}}:{}),Relaxation:{coffee:'Drink coffee',sofa:'Sit on sofa',phone:'Use phone',tv:'Watch TV',relax:'Relax'}};
 for(const [category,items] of Object.entries(actions)){const title=document.createElement('h3');title.textContent=category;d.append(title);for(const [key,label] of Object.entries(items)){const button=document.createElement('button');button.textContent=label;button.onclick=()=>{d.close();if(key==='followActor'){const picker=makeDialog('followDialog','Follow a companion');for(const targetActor of actors.filter(b=>b!==a)){const button=document.createElement('button');button.textContent=targetActor.profile.name;button.onclick=()=>{leisure.release(a);a.followTarget=targetActor.id;a.auto=false;a.manual=false;picker.close();toast('Following '+targetActor.profile.name)};picker.append(button)}picker.showModal();}else if(key==='handshake'){const partner=actors.find(b=>b!==a&&b.floor===a.floor&&!online(b)&&!b.match);if(!partner){toast('No available offline companion nearby.');return}leisure.release(a);leisure.release(partner);const pos=partner.rig.model.position;if(!routeActor(a,{x:pos.x,z:pos.z+1.0,floor:a.floor},world)){toast('No clear route to colleague.');return}a.auto=false;partner.auto=false;const timer=setInterval(()=>{if(disposed||!actors.includes(a)||!actors.includes(partner)){clearInterval(timer);return}if(!a.path.length){a.rig.model.rotation.y=Math.PI;partner.rig.model.rotation.y=0;a.state=partner.state='handshake';a.rig.actions.handshake.reset();partner.rig.actions.handshake.reset();setTimeout(()=>{if(disposed)return;if(!a.match)a.state='idle';if(!partner.match){partner.state='idle';partner.auto=true;partner.next=performance.now()+3000}},4000);clearInterval(timer)}},200)}else if(key==='coffee'){leisure.choose(a,'coffee')}else if(['sofa','tv','relax'].includes(key)){leisure.choose(a,'rooftop')}else act(key)};d.append(button)}}const button=document.createElement('button');button.textContent='Leisure →';button.className='primary';button.onclick=()=>{d.close();openLeisure()};d.append(button);d.showModal();}
const socialRequests=new Map();
function requestSocial(data){return new Promise((resolve,reject)=>{const requestId=crypto.randomUUID(),timer=setTimeout(()=>{socialRequests.delete(requestId);reject(new Error('No confirmation received. Check the activity before retrying.'));},20000);socialRequests.set(requestId,result=>{clearTimeout(timer);socialRequests.delete(requestId);result.ok?resolve(result):reject(new Error(result.error||'Invitation failed. Please retry.'));});post({type:'KEYHQ_SOCIAL',...data,requestId});});}
function openLeisure(preselected,invite=false){const a=actors.find(a=>a.id===selected);if(!a||!canControl(a,session,embedded))return;if(a.lift||a.vehicle){toast('Exit before starting a leisure activity.');return}activityDialog({a,preselected:typeof preselected==='string'?preselected:undefined,invite,actors,session,leisure,games,dialog:makeDialog,request:requestSocial,stop:stopActivity,onStart:()=>{beginActivityCamera();selectFloor('all',true);canvas.focus({preventScroll:true});}});}
const leaveButton=document.createElement('button');leaveButton.textContent='Leave activity';leaveButton.onclick=()=>{const a=actors.find(a=>a.id===selected);if(!a||!canControl(a,session,embedded))return;if(a.diving)diving.cancel(a);const m=leisure.matches.get(a.match);if(a.gameActive){games.exit(a);return true;}if(m?.remote)post({type:'KEYHQ_SOCIAL',action:m.host===session.userId?'end':'leave',id:m.id,requestId:crypto.randomUUID()});else{leisure.release(a);a.state='idle';a.auto=false;}};$('actionsBody').append(leaveButton);
const leisureButton=document.createElement('button');leisureButton.textContent='Leisure';leisureButton.id='leisure';leisureButton.onclick=openLeisure;leisureButton.hidden=true;$('actionsBody').append(leisureButton);const interactionButton=document.createElement('button');interactionButton.textContent='More actions';interactionButton.onclick=()=>{const a=actors.find(a=>a.id===selected);if(a)openActions(a)};interactionButton.hidden=true;$('actionsBody').append(interactionButton);
leisure.statusChanged=()=>{const a=actors.find(a=>a.id===selected),m=a?.match&&leisure.matches.get(a.match);if(m)$('actorStatus').textContent=activities[m.activity].name+' · '+(m.status==='playing'?'Playing':activities[m.activity].min>1?'Waiting for Opponent':'Travelling')};

const ridePassengers=document.createElement('button');ridePassengers.id='ridePassengers';ridePassengers.textContent='Invite passengers';ridePassengers.hidden=true;$('cart').after(ridePassengers);
ridePassengers.onclick=()=>{const a=actors.find(a=>a.id===selected),v=a?.vehicle;if(!a||!canControl(a,session,embedded)||!v||v.host!==session.userId)return;const d=makeDialog('vehicleDialog','Ride passengers');const candidates=actors.filter(b=>b!==a&&!b.vehicle&&b.userId&&!b.visitor);for(const b of candidates){const button=document.createElement('button');button.textContent='Invite '+b.profile.name;button.onclick=()=>{post({type:'KEYHQ_SOCIAL',action:'invite',id:v.session,userId:b.userId,requestId:crypto.randomUUID()});d.close()};d.append(button)}if(!candidates.length){const p=document.createElement('p');p.textContent='No passengers are available.';d.append(p)}d.showModal();};
$('cart').onclick=()=>{const a=actors.find(a=>a.id===selected);if(a&&canControl(a,session,embedded)){vehicles.enter(a);canvas.focus({preventScroll:true});}};
window.addEventListener('keydown',e=>{if(e.key!=='Enter'||e.repeat||/INPUT|TEXTAREA|SELECT|BUTTON/.test(e.target.tagName)||document.querySelector('dialog[open]'))return;const a=actors.find(a=>a.id===selected);if(a&&canControl(a,session,embedded)){e.preventDefault();vehicles.enter(a)}});

$('autoMode').onclick=()=>setControl(false);$('manualMode').onclick=()=>setControl(true);
$('movementSelect').onchange=e=>{act(e.target.value)};
