const divePanel=document.createElement('section');divePanel.className='panel dive-controls';divePanel.hidden=true;divePanel.innerHTML='<b id="diveLevel">Diving tower</b><p id="diveHint"></p><label>Style <select id="diveStyle"><option value="forward">Forward</option><option value="backward">Backward</option><option value="twisting">Twisting</option></select></label><label>Spins <select id="diveSpins"></select></label><button id="jumpDive">Jump</button>';document.body.appendChild(divePanel);
function updateDiveControls(){const a=actors.find(a=>a.id===selected),p=a?.rig.model.position,level=a&&diving.levelAt(a);divePanel.hidden=!a||!canControl(a,session,embedded)||a.floor!=='all'||p.x<69||p.x>82||p.z<26||p.z>48||!!a.diving;if(divePanel.hidden)return;$('diveLevel').textContent=level?level+' m platform':'Diving tower · 10 / 20 / 30 m';$('diveHint').textContent=level?'Choose your dive, then jump.':'Use movement controls to climb the stairs and walk to a platform end.';$('jumpDive').disabled=!level;const max=level?diving.maxSpins(level):0;if($('diveSpins').dataset.max!==String(max)){const previous=Number($('diveSpins').value)||0;$('diveSpins').innerHTML=Array.from({length:max+1},(_,n)=>'<option>'+n+'</option>').join('');$('diveSpins').value=String(Math.min(previous,max));$('diveSpins').dataset.max=String(max);}}
$('jumpDive').onclick=()=>{const a=actors.find(a=>a.id===selected);if(a&&canControl(a,session,embedded)&&diving.jump(a,$('diveStyle').value,$('diveSpins').value)){keys.clear();canvas.focus({preventScroll:true});}};
$('divePlatform').onclick=()=>{const a=actors.find(a=>a.id===selected);if(!a||!canControl(a,session,embedded))return;if(a.manual){toast('Walk to the tower stairs on the north pool deck. Climb to 10, 20 or 30 m, then choose your dive at the platform end.');return;}const d=makeDialog('divingDialog','Walk to diving platform');for(const level of divingLevels){const b=document.createElement('button');b.textContent=level+' m';b.onclick=()=>{if(stopActivity(a)&&diving.start(a,level)){d.close();selectFloor('all');}else toast('No clear route to the diving staircase.');};d.append(b);}d.showModal();};
$('inviteLeisure').onclick=()=>openLeisure($('leisureSelect').value||undefined,true);
const panel=document.querySelector('.actions-panel'),resize=$('actionsResize');let sizing=null;
function resizeActions(height){const h=Math.max(160,Math.min(height,innerHeight-panel.getBoundingClientRect().top-100));$('actionsBody').style.height=h+'px';try{storage.setItem('keyhq:actions:height',h)}catch{}}
try{const saved=Number(storage.getItem('keyhq:actions:height'));if(saved)resizeActions(saved)}catch{}
resize.onpointerdown=e=>{sizing={y:e.clientY,h:$('actionsBody').getBoundingClientRect().height};resize.setPointerCapture(e.pointerId);e.preventDefault()};resize.onpointermove=e=>{if(sizing)resizeActions(sizing.h+e.clientY-sizing.y)};resize.onpointerup=resize.onpointercancel=()=>sizing=null;resize.onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();resizeActions($('actionsBody').clientHeight+(e.key==='ArrowDown'?20:-20))}};
window.addEventListener('resize',()=>{if($('actionsBody').style.height)resizeActions($('actionsBody').clientHeight)});
const joystick=$('joystick');let stickPointer=null;
function moveStick(e){const r=joystick.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)/(r.width*.35),y=(e.clientY-r.top-r.height/2)/(r.height*.35),n=Math.max(1,Math.hypot(x,y));stick.x=x/n;stick.y=y/n;joystick.firstElementChild.style.transform=`translate(${stick.x*35}px,${stick.y*35}px)`;vehicles.analog=stick;}
joystick.onpointerdown=e=>{stickPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);moveStick(e);e.preventDefault()};joystick.onpointermove=e=>{if(e.pointerId===stickPointer)moveStick(e)};joystick.onpointerup=joystick.onpointercancel=()=>{stickPointer=null;stick.x=stick.y=0;joystick.firstElementChild.style.transform='';};
window.addEventListener('blur',()=>{stick.x=stick.y=0});

const smart=$('smartActions');let smartSignature='';
function updateSmartActions(){const a=actors.find(a=>a.id===selected),allowed=a&&canControl(a,session,embedded);if(!a)return;const p=a.rig.model.position,nearVehicle=vehicles.near(a),outdoor=a.floor==='all'||a.floor==='roof';$('cart').hidden=!allowed;ridePassengers.hidden=!allowed||!a.vehicle||a.vehicle.host!==session.userId||a.vehicle.spec.capacity<2;$('cart').textContent=a.vehicle?'Exit Vehicle':'Ride Vehicle';$('smoke').hidden=!allowed||!outdoor;$('elevatorControl').hidden=!allowed||Math.hypot(p.x+35,p.z+8.6)>4;
 const entries=[];if(allowed){if(a.seating)entries.push(['Stand up',()=>{if(!seating.stand(a))toast('No safe space to stand.')}]);else if(!a.match&&!a.vehicle&&!a.lift&&seating.available(a).some(s=>s.hip.distanceTo(p)<3))entries.push(['Sit',()=>seating.sit(a)]);
 if(a.match)entries.push(['Exit Activity',()=>games.exit(a)]);else if(!a.vehicle&&!a.lift){for(const [key,spec]of Object.entries(activities)){if(spec.floor===a.floor&&Math.hypot(p.x-spec.x,p.z-spec.z)<(key==='swim'?6:key==='football'?30:10))entries.push([({swim:'Swim',gym:'Workout',basketball:'Play Basketball'})[key]||spec.name,()=>openLeisure(key)]);}}
 if(a.carry)entries.push(['Stop Activity',()=>stopCarry(a)]);}
 const signature=a.id+'|'+entries.map(e=>e[0]).join('|');if(signature!==smartSignature){smartSignature=signature;smart.replaceChildren();for(const [label,fn]of entries){const b=document.createElement('button');b.textContent=label;b.onclick=fn;smart.append(b)}}
 if(!a.gameActive)$('hint').textContent=a.vehicle?'Arrows / joystick: drive · Enter: dismount · Stop before exiting':a.lift?'Elevator travelling · walking resumes at the selected floor':a.seating?'Seated · Stand up to walk':'Arrow keys: walk / turn · Drag: camera · Wheel: zoom · Enter near a vehicle: ride';
}
function stopCarry(a){carry.stop(a);}
function startCarry(a,mode){carry.start(a,mode);canvas.focus({preventScroll:true});}
$('smoke').onclick=()=>{const a=actors.find(a=>a.id===selected);if(!a||!canControl(a,session,embedded)||!['all','roof'].includes(a.floor))return;const d=makeDialog('smokeDialog','Take a break');for(const mode of ['coffee','smoke','beer','both']){const b=document.createElement('button');b.textContent=mode[0].toUpperCase()+mode.slice(1);b.onclick=()=>{startCarry(a,mode);d.close()};d.append(b)}d.showModal();};
function updateCarry(dt,now){carry.update(actors,dt,now);}
canvas.addEventListener('pointermove',e=>{if(!games.focus)return;pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);raycaster.setFromCamera(pointer,camera);const plane=new T.Plane(new T.Vector3(0,1,0),-1.3),point=new T.Vector3();if(raycaster.ray.intersectPlane(plane,point))games.aim={x:T.MathUtils.clamp(point.x,-150,150),y:games.focus.activity==='basketball'?3.15:1.3,z:T.MathUtils.clamp(point.z,-150,150)};});

// Dialog closure returns keys to the scene without stealing focus from text entry.
